    echo
    if [[ ! $REPLY =~ ^[Yy]$ ]]; then
        echo "Aborted. Please commit or stash your changes first."
        exit 1
    fi
fi

# Get commit message
COMMIT_MSG=$(git log -1 --format="%s")
COMMIT_DATE=$(git log -1 --format="%ad" --date=iso)

echo "📝 Current State:"
echo "   Branch: $CURRENT_BRANCH"
echo "   Commit: $CURRENT_COMMIT"
echo "   Message: $COMMIT_MSG"
echo "   Date: $COMMIT_DATE"
echo ""

# Confirm
read -p "Create backup from this state? (y/N): " -n 1 -r
echo
if [[ ! $REPLY =~ ^[Yy]$ ]]; then
    echo "Aborted."
    exit 1
fi

# Create backup branch
echo ""
echo "🔨 Creating backup branch..."
git branch "$BACKUP_BRANCH" "$CURRENT_COMMIT"
echo "   ✅ Created branch: $BACKUP_BRANCH"

# Create backup tag
echo ""
echo "🏷️  Creating backup tag..."
git tag -a "$BACKUP_TAG" -m "Production backup: $DESCRIPTION" "$CURRENT_COMMIT"
echo "   ✅ Created tag: $BACKUP_TAG"

# Push to remote
echo ""
echo "📤 Pushing to remote..."
read -p "Push backup to remote? (y/N): " -n 1 -r
echo
if [[ $REPLY =~ ^[Yy]$ ]]; then
    git push origin "$BACKUP_BRANCH"
    git push origin "$BACKUP_TAG"
    echo "   ✅ Pushed to remote"
else
    echo "   ⏭️  Skipped remote push"
fi

# Create backup info file
BACKUP_INFO_FILE="BACKUP_INFO_${BACKUP_DATE}_${BACKUP_TIME}.txt"
cat > "$BACKUP_INFO_FILE" << EOF
# Production Backup Information
Created: $(date)
Backup Date: $BACKUP_DATE $BACKUP_TIME
Description: $DESCRIPTION

## Backup References
- Branch: $BACKUP_BRANCH
- Tag: $BACKUP_TAG
- Commit: $CURRENT_COMMIT
- Commit Message: $COMMIT_MSG
- Commit Date: $COMMIT_DATE

## Revert Commands
To revert to this backup:

\`\`\`bash
# Method 1: Use backup branch
git reset --hard $BACKUP_BRANCH

# Method 2: Use backup tag
git reset --hard $BACKUP_TAG

# Method 3: Use commit hash
git reset --hard $CURRENT_COMMIT
\`\`\`

## View This Backup
\`\`\`bash
git show $BACKUP_BRANCH
git log $BACKUP_BRANCH -1
\`\`\`
EOF

echo ""
echo "✅ Backup created successfully!"
echo ""
echo "📋 Backup Information:"
echo "   Branch: $BACKUP_BRANCH"
echo "   Tag: $BACKUP_TAG"
echo "   Commit: $CURRENT_COMMIT"
echo "   Info file: $BACKUP_INFO_FILE"
echo ""
echo "📝 To revert to this backup later:"
echo "   git reset --hard $BACKUP_BRANCH"
echo "   # or"
echo "   git reset --hard $BACKUP_TAG"
echo ""
echo "💡 Tip: Use './scripts/revert-to-backup.sh $BACKUP_BRANCH' for an interactive revert"












